// Inline, CSS-animated SEO service illustrations (SVGs in ./svg, generated by
// `node scripts/build-ikas-visuals.mjs seo`). Same contract as
// MarketplaceArtwork: final state in the HTML, motion opt-in via
// IkasMotionScope (`ikas-visible` once, `ikas-in-view` for loops; mounted by
// CustomEcommerceMotionScope), CSS under "seo visuals" in globals.css, reduced
// motion shows the end state. Every chart/report is representative: no
// numbers, percentages or live-looking counters.

import { SEO_VISUALS, type SeoVisualName } from './generated';

interface SeoArtworkProps {
  name: SeoVisualName;
  /** Accessible description; omit for purely decorative use. */
  label?: string;
  /** HTML labels for `slot-*` boxes (keyed by slot id). */
  slotLabels?: Record<string, string>;
  /** Keep ambient loops running while on screen. */
  loop?: boolean;
  className?: string;
}

export default function SeoArtwork({ name, label, slotLabels, loop = false, className = '' }: SeoArtworkProps) {
  const visual = SEO_VISUALS[name];
  const slots = visual.slots as Record<string, { left: number; top: number; width: number; height: number }>;
  return (
    <figure
      data-ikas-reveal=""
      className={`seo-art seo-art--${name} relative m-0 ${className}`}
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
    >
      <div data-ikas-loop={loop ? '' : undefined} className="sev-art" dangerouslySetInnerHTML={{ __html: visual.markup }} />
      {Object.entries(slots).map(([id, box]) => {
        const text = slotLabels?.[id];
        if (!text) return null;
        const style = { left: `${box.left}%`, top: `${box.top}%`, width: `${box.width}%`, height: `${box.height}%` };
        return <span key={id} aria-hidden="true" className={`sev-slot sev-${id} absolute flex items-center overflow-hidden whitespace-nowrap text-[clamp(8px,1.15vw,12.5px)] font-semibold leading-tight text-gray-700`} style={style}>{text}</span>;
      })}
    </figure>
  );
}
